source('R/stile.R')
w<-leggi('co2_settimanale_storica.csv');w$data<-as.Date(w$data)
d<-leggi('co2_mensile_derivata.csv');d$data<-as.Date(d$data)
t<-leggi('temperatura_simulata.csv');t$data<-as.Date(t$data);p<-leggi('processi_simulati.csv')
salva('M09','F01',ggplot(d,aes(data,co2_ppm))+geom_line(colour=geo[1],linewidth=.55)+scale_x_date(date_breaks='10 years',date_labels='%Y')+labs(x='Anno',y='CO₂ (ppm)'))
z<-data.frame(Settimane=factor(0:5),Mesi=as.numeric(table(factor(d$n_settimane,levels=0:5))))
salva('M09','F02',ggplot(z,aes(Settimane,Mesi))+geom_col(fill=geo[2],width=.65)+labs(x='Valori settimanali nel mese',y='Numero di mesi'))
u<-t[1:60,];u$media3<-as.numeric(stats::filter(u$temperatura_C,rep(1/3,3),sides=2));u$media13<-as.numeric(stats::filter(u$temperatura_C,rep(1/13,13),sides=2))
salva('M09','F03',ggplot(u,aes(data,temperatura_C))+geom_line(colour=geo[6],linewidth=.5)+geom_line(aes(y=media3,colour='3 mesi'),linewidth=.9,na.rm=TRUE)+geom_line(aes(y=media13,colour='13 mesi'),linewidth=.9,na.rm=TRUE)+scale_colour_manual(values=geo[1:2])+scale_x_date(breaks=as.Date(c('2000-01-01','2002-01-01','2004-01-01')),date_labels='%Y')+labs(x='Anno',y='Temperatura (°C)'))
z<-rbind(data.frame(t[1:60,c('data','temperatura_C')],Componente='Osservata'),data.frame(data=t$data[1:60],temperatura_C=t$trend_simulato[1:60]+t$stagione_simulata[1:60],Componente='Trend + stagione'))
salva('M09','F04',ggplot(z,aes(data,temperatura_C,colour=Componente))+geom_line(linewidth=.8)+scale_colour_manual(values=geo[c(2,1)])+guides(colour=guide_legend(nrow=2))+scale_x_date(breaks=as.Date(c('2000-01-01','2002-01-01','2004-01-01')),date_labels='%Y')+labs(x='Anno',y='Temperatura (°C)'))
t$mese<-as.integer(format(t$data,'%m'));base<-aggregate(temperatura_C~mese,t[t$data<as.Date('2005-01-01'),],mean);t$anomalia<-t$temperatura_C-base$temperatura_C[match(t$mese,base$mese)]
salva('M09','F05',ggplot(t,aes(data,anomalia))+geom_hline(yintercept=0,colour=geo[6])+geom_line(colour=geo[1],linewidth=.55)+scale_x_date(date_breaks='5 years',date_labels='%Y')+labs(x='Anno',y='Anomalia (°C)'))
z<-data.frame(Passato=head(p$ar1,-1),Presente=tail(p$ar1,-1))
salva('M09','F06',ggplot(z,aes(Passato,Presente))+geom_point(colour=geo[1],alpha=.55,size=1.6)+geom_smooth(method='lm',formula=y~x,se=FALSE,colour=geo[2],linewidth=1)+labs(x='X al passo t − 1',y='X al passo t'))
a<-acf(p$ar1,lag.max=24,plot=FALSE);z<-data.frame(Lag=as.numeric(a$lag)[-1],ACF=as.numeric(a$acf)[-1]);z$Teorica<-.65^z$Lag
salva('M09','F07',ggplot(z,aes(Lag,ACF))+geom_hline(yintercept=0,colour=geo[6])+geom_segment(aes(xend=Lag,yend=0),colour=geo[1],linewidth=.8)+geom_line(aes(y=Teorica),colour=geo[2],linewidth=1)+geom_hline(yintercept=c(-1,1)*1.96/sqrt(nrow(p)),linetype=2,colour=geo[6])+scale_x_continuous(breaks=c(1,6,12,18,24))+labs(x='Ritardo (passi)',y='Autocorrelazione'))
z<-rbind(data.frame(passo=p$passo,Valore=p$ar1,Processo='AR(1)'),data.frame(passo=p$passo,Valore=p$random_walk,Processo='Random walk'));z$Processo<-factor(z$Processo,levels=c('AR(1)','Random walk'))
salva('M09','F08',ggplot(z,aes(passo,Valore))+geom_line(colour=geo[1],linewidth=.5)+facet_wrap(~Processo,ncol=1,scales='free_y')+scale_x_continuous(breaks=c(0,150,300))+scale_y_continuous(n.breaks=3)+labs(x='Passo',y='Valore'))
c2<-leggi('co2_1985_2001.csv');c2$data<-as.Date(c2$data);yy<-c2$co2_ppm;z<-rbind(data.frame(data=c2$data[-1],Valore=diff(yy),Serie='Differenza a 1 mese'),data.frame(data=c2$data[-(1:12)],Valore=diff(yy,lag=12),Serie='Differenza a 12 mesi'))
salva('M09','F09',ggplot(z,aes(data,Valore))+geom_hline(yintercept=0,colour=geo[6])+geom_line(colour=geo[2],linewidth=.5)+facet_wrap(~Serie,ncol=1,scales='free_y')+scale_x_date(date_breaks='8 years',date_labels='%Y')+scale_y_continuous(n.breaks=3)+labs(x='Anno',y='Variazione CO₂ (ppm)'))
set.seed(919);e<-rnorm(3000);z<-data.frame(Lag=1:12,ACF=as.numeric(acf(diff(e),plot=FALSE,lag.max=12)$acf)[-1])
salva('M09','F10',ggplot(z,aes(Lag,ACF))+geom_segment(aes(xend=Lag,yend=0),colour=geo[2],linewidth=1)+geom_hline(yintercept=0,colour=geo[6])+geom_point(data=data.frame(Lag=1,ACF=-.5),colour=geo[3],size=3)+scale_x_continuous(breaks=c(1,4,8,12))+labs(x='Ritardo (passi)',y='ACF delle differenze'))
verifica('griglia mensile',identical(d$data,seq(min(d$data),max(d$data),by='month')))
verifica('date senza duplicati',!anyDuplicated(w$data) && !anyNA(w$data))
verifica('componenti temperatura',max(abs(t$temperatura_C-t$trend_simulato-t$stagione_simulata-t$residuo_simulato))<2e-8)
verifica('ricostruzione livelli',max(abs(c(yy[1],yy[1]+cumsum(diff(yy)))-yy))<1e-10)
verifica('differenze commutano',max(abs(diff(diff(yy,12))-diff(diff(yy),12)))<1e-10)
# Verifica formula ACF con il medesimo denominatore di stats::acf.
x<-p$ar1-mean(p$ar1);manuale<-sum(head(x,-1)*tail(x,-1))/sum(x^2)
verifica('ACF campionaria',abs(manuale-a$acf[2])<1e-12)
verifica('sovradifferenziazione simulata',abs(z$ACF[1]+.5)<.05)
# tseries è richiesto qui: un ramo saltato non viene contato come verifica eseguita.
stopifnot(requireNamespace('tseries',quietly=TRUE))
ris<-lapply(c('rumore_bianco','ar1','random_walk'),function(n){x<-p[[n]];ad<-tseries::adf.test(x,k=4);kp<-tseries::kpss.test(x,null='Level');kt<-tseries::kpss.test(x,null='Trend');data.frame(Serie=n,Test=c('ADF costante e trend, k=4','KPSS livello','KPSS trend'),Statistica=c(ad$statistic,kp$statistic,kt$statistic),p_riportato=c(ad$p.value,kp$p.value,kt$p.value))})
dir.create('risultati/M09',recursive=TRUE,showWarnings=FALSE);write.csv(do.call(rbind,ris),'risultati/M09/test_stazionarieta.csv',row.names=FALSE)
verifica('test ADF KPSS eseguiti',length(ris)==3)
